class Dashboard{constructor(form){this.form=form;this.sensors=$("#sensors");this.sensor=$("#sensor");this.type=$("input[name=type]");this.utrechtRows=this.sensors.data("sensors");this.sensorsArray=this.getSensorsArray(this.utrechtRows);const vectorSource=new ol.source.Vector({features:this.sensorsArray});const vectorLayer=new ol.layer.Vector({source:vectorSource});this.map=new ol.Map({layers:[new ol.layer.Tile({source:new ol.source.OSM}),vectorLayer],target:document.getElementById("map"),view:new ol.View({center:ol.proj.fromLonLat([5.11,52.1]),zoom:12.5})});this.popup=new ol.Overlay({element:$("#popup")[0],positioning:"bottom-center",stopEvent:false});this.map.addOverlay(this.popup);this.map.on("click",this.mapClick.bind(this));this.map.on("pointermove",this.mapPointer.bind(this));this.map.on("movestart",this.disposePopover.bind(this));this.sensor.on("change",this.sensorChange.bind(this));this.type.on("change",this.graph.bind(this));this.graph()}getSensorsArray(utrechtRows){let sensorsArray=[];utrechtRows.forEach(index=>{let date=index[0];date=new Date(date+" UTC").toLocaleString();let temperature=index[2];let humidity=index[5];let pm25=index[9];let pm10=index[10];let sourceImage;let timestamps=$("#sensor-"+index[1]+"-timestamps");if($("#pm:checked").length===1&&index[19]==="0"){return}if($("#inactive:checked").length===0&&timestamps.length===0){return}if(timestamps.length===0){sourceImage="/static/img/sensor-red.png"}else{sourceImage="/static/img/sensor-green.png"}let sensor=new ol.Feature({geometry:new ol.geom.Point(ol.proj.fromLonLat([index[13],index[14]])),id:index[1],longitude:index[13],latitude:index[14],name:'<p class="sensor-title">Sensor '+index[1]+"</p>"+"<p>"+date+"</p>"+"<p>Temperatuur: "+this.displayFloat(temperature)+" °C</p>"+"<p>Luchtvochtigheid: "+this.displayFloat(humidity)+" RV %</p>"+"<p>Fijnstof 2.5: "+this.displayFloat(pm25)+" µg/m³</p>"+"<p>Fijnstof 10: "+this.displayFloat(pm10)+" µg/m³</p>"});sensor.setStyle(new ol.style.Style({image:new ol.style.Icon({crossOrigin:"anonymous",src:sourceImage,width:30,height:30})}));sensorsArray.push(sensor)});return sensorsArray}popupIcon(evt){let feature;if(typeof evt==="object"){feature=this.map.forEachFeatureAtPixel(evt.pixel,function(feature){return feature})}else{this.sensorsArray.forEach(function(element){if(element.get("id")===evt){feature=element}})}this.disposePopover();if(!feature){return 0}if(typeof evt==="object"){this.popup.setPosition(evt.coordinate)}else{this.popup.setPosition(ol.proj.fromLonLat([feature.get("longitude"),feature.get("latitude")]))}this.popover=new bootstrap.Popover($("#popup")[0],{placement:"top",html:true,content:feature.get("name")});this.popover.show();if(typeof evt==="object"){this.sensor.val(feature.get("id"));this.graph()}return evt}mapClick(event){if(this.popupIcon(event)){this.sensor.val()}}mapPointer(event){const hit=this.map.hasFeatureAtPixel(event.pixel);this.map.getTargetElement().style.cursor=hit?"pointer":""}sensorChange(){this.popupIcon(this.sensor.val());graph()}disposePopover(){if(this.popover){this.popover.dispose();this.popover=undefined}}displayFloat(value){if(value!==0){return(Math.round(value*10)/10).toFixed(1)}else{return"N/B"}}graph(){google.charts.load("current",{packages:["corechart"]});google.charts.setOnLoadCallback(this.drawChart)}drawChart(){let id=$("#sensor").val();let vertical="°C";let horizontal="t";let horizontalData=[new Date];let verticalData=[0];let type=$("input[name=type]:checked").val();let title="Temperatuur";let rawData=$("#sensor-"+id+"-timestamps");if(id!==""&&rawData.length>0){rawData=rawData.data("timestamps");horizontalData=[];rawData.forEach(function(element){let date=new Date(element+" UTC");horizontalData.push(date)});if(type==="temperature"){title="Temperatuur";vertical="°C";verticalData=$("#sensor-"+id+"-temperatures").data("temperatures")}else if(type==="humidity"){title="Luchtvochtigheid";vertical="RV %";verticalData=$("#sensor-"+id+"-humidities").data("humidities")}else if(type==="pm25"){title="Fijnstof 2.5 µm";vertical="µg/m³";verticalData=$("#sensor-"+id+"-pm25s").data("pm25s")}else if(type==="pm10"){title="Fijnstof 10 µm";vertical="µg/m³";verticalData=$("#sensor-"+id+"-pm10s").data("pm10s")}}else{if(type==="temperature"){title="Temperatuur";vertical="°C"}else if(type==="humidity"){title="Luchtvochtigheid";vertical="RV %"}else if(type==="pm25"){title="Fijnstof 2.5 µm";vertical="µg/m³"}else if(type==="pm10"){title="Fijnstof 10 µm";vertical="µg/m³"}}let indices=[];verticalData.forEach(function(element,index){if(element===null){indices.push(index)}});for(var i=indices.length-1;i>=0;i--){horizontalData.splice(indices[i],1);verticalData.splice(indices[i],1)}if(horizontalData.length===0||verticalData.length===0){verticalData=[0];horizontalData=[new Date]}let dataGraph=horizontalData.map((name,index)=>[name,verticalData[index]]);let data=google.visualization.arrayToDataTable([[horizontal,vertical]].concat(dataGraph));let options={title:title,curveType:"function",vAxis:{title:vertical},hAxis:{title:horizontal,format:"MM-dd HH:mm"},legend:{position:"none"}};let chart=new google.visualization.LineChart(document.getElementById("curve_chart"));chart.draw(data,options)}}